const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function candles(f,{reveal=false,region=false}={}){const bars=f.bars.slice(0,f.cutoff),values=bars.flatMap(b=>[b.high,b.low]).concat(f.line||[]),min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.12,.05),lo=min-pad,hi=max+pad,y=p=>30+(hi-p)/(hi-lo)*240,x=i=>55+(i+.5)*620/bars.length,w=Math.min(27,420/bars.length),vmax=Math.max(...bars.map(b=>b.volume));return `<svg class="candlestick" viewBox="0 0 760 390" role="img" aria-label="Synthetic stock candlesticks. Each bar is ${esc(f.timeframe)}. Price in USD; volume in shares."><title>Synthetic stock candles, ${esc(f.timeframe)} per bar</title><desc>Original illustrative prices and volume. No historical data. Only the supplied decision-time bars are shown.</desc><rect width="760" height="390" fill="#111713"/>${[0,1,2,3,4].map(i=>{const p=hi-(hi-lo)*i/4,yy=y(p);return `<line x1="45" x2="690" y1="${yy}" y2="${yy}" stroke="#354038"/><text x="698" y="${yy+5}" fill="#c4d0c7" font-size="14">${p.toFixed(2)}</text>`}).join('')}<text x="48" y="18" fill="#c4d0c7" font-size="14">Price · USD</text>${region?[0,1,2].map(i=>`<g class="chart-region" role="button" tabindex="0" data-region="r${i}" aria-label="Select region ${'ABC'[i]}: ${['early','middle','latest'][i]} bars"><rect x="${45+i*215}" y="28" width="210" height="250" fill="${['#53779c','#8b7856','#698c66'][i]}" fill-opacity=".12" stroke="#738275" stroke-dasharray="4 5"/><text x="${55+i*215}" y="48" fill="#e4eee3" font-size="17">${'ABC'[i]}</text></g>`).join(''):''}${bars.map((b,i)=>{const up=b.close>=b.open,color=up?'#b3ef7c':'#ff9a9a';return `<g><line x1="${x(i)}" x2="${x(i)}" y1="${y(b.high)}" y2="${y(b.low)}" stroke="${color}" stroke-width="2"/><rect x="${x(i)-w/2}" y="${Math.min(y(b.open),y(b.close))}" width="${w}" height="${Math.max(2,Math.abs(y(b.open)-y(b.close)))}" fill="${up?color:'#111713'}" stroke="${color}" stroke-width="2"/><rect x="${x(i)-w/2}" y="${340-b.volume/vmax*40}" width="${w}" height="${b.volume/vmax*40}" fill="${color}" opacity=".65"/><text x="${x(i)}" y="365" fill="#b5c2b8" font-size="12" text-anchor="middle">${i+1}</text></g>`}).join('')}${f.line?`<polyline points="${f.line.slice(0,bars.length).map((v,i)=>x(i)+','+y(v)).join(' ')}" fill="none" stroke="#88bdf7" stroke-width="2.5"/><text x="270" y="18" fill="#88bdf7" font-size="14">${esc(f.lineLabel)}</text>`:''}${reveal?`${f.highlightRegion!==undefined?`<rect x="${45+f.highlightRegion*215}" y="25" width="210" height="253" fill="#b3ef7c" fill-opacity=".07" stroke="#b3ef7c" stroke-dasharray="5 4"/>`:(f.focusBars||bars.map((_,i)=>i)).map(i=>`<rect x="${x(i)-w/2-4}" y="${y(bars[i].high)-6}" width="${w+8}" height="${Math.max(10,y(bars[i].low)-y(bars[i].high)+12)}" fill="none" stroke="#b3ef7c" stroke-dasharray="3 3"/>`).join('')}<text x="48" y="294" fill="#b3ef7c" font-size="13">Highlighted: candles or region discussed in the explanation.</text>`:''}<text x="48" y="385" fill="#c4d0c7" font-size="13">Bar number · ${esc(f.timeframe)} per bar · volume maximum ${vmax.toLocaleString('en-US')} shares</text></svg>`}
export function chartTable(f){return `<details class="chart-data"><summary>Accessible candle data</summary><div class="table-wrap"><table><caption>Fictional bars; prices USD, volume shares; ${esc(f.timeframe)} per bar</caption><thead><tr><th>Bar</th><th>Open</th><th>High</th><th>Low</th><th>Close</th><th>Volume</th>${f.line?'<th>Indicator</th>':''}</tr></thead><tbody>${f.bars.slice(0,f.cutoff).map((b,i)=>`<tr><th scope="row">${i+1}</th>${['open','high','low','close'].map(k=>`<td>${b[k].toFixed(2)}</td>`).join('')}<td>${b.volume}</td>${f.line?`<td>${f.line[i].toFixed(2)}</td>`:''}</tr>`).join('')}</tbody></table></div></details>`}
